"use client";

import { FormEvent, ReactNode, useState } from "react";
import { siteVisuals, SiteVisual, visualForRoute } from "./visualData";

type Language = "en" | "zh";
type LocalText = { en: string; zh: string };
type LinkItem = { title: LocalText; copy: LocalText; path?: string };
type PageSection = {
  id: string;
  eyebrow: LocalText;
  title: LocalText;
  copy: LocalText;
  items: LinkItem[];
  mode?: "cards" | "steps" | "list";
};
type RichPageSpec = {
  eyebrow: LocalText;
  title: LocalText;
  copy: LocalText;
  audience: LocalText;
  purpose: LocalText;
  status: LocalText;
  primary: { label: LocalText; path: string };
  secondary?: { label: LocalText; path: string };
  visual?: SiteVisual;
  sections: PageSection[];
  related: LinkItem[];
  proof: "history" | "events" | "regional" | "network" | "governance";
  close: { title: LocalText; copy: LocalText };
};

const L = (en: string, zh: string): LocalText => ({ en, zh });
const tx = (value: LocalText, lang: Language) => value[lang];
const hrefFor = (lang: Language, path = "") => `/${lang}${path ? `/${path}` : ""}`;
const Arrow = () => <span aria-hidden="true">↗</span>;
const item = (en: string, zh: string, enCopy: string, zhCopy: string, path?: string): LinkItem => ({
  title: L(en, zh), copy: L(enCopy, zhCopy), path,
});

