function RichHero({ lang, path, spec }: { lang: Language; path: string; spec: RichPageSpec }) {
  const visual = spec.visual ?? visualForRoute(path);
  return (
    <section className="page-hero inner-page-hero rich-page-hero">
      <figure className="page-hero-photo">
        <img src={visual.src} alt={tx(visual.alt, lang)} />
        <figcaption>{tx(visual.caption, lang)}</figcaption>
      </figure>
      <div className="page-hero-art" aria-hidden="true"><i /><i /><i /><span>W+</span></div>
      <div className="shell">
        <p className="eyebrow light">{tx(spec.eyebrow, lang)}</p>
        <h1>{tx(spec.title, lang)}</h1>
        <p>{tx(spec.copy, lang)}</p>
        <div className="inner-hero-actions">
          <a className="button button-light" href={hrefFor(lang, spec.primary.path)}>{tx(spec.primary.label, lang)} <Arrow /></a>
          {spec.secondary && <a className="text-link light-link" href={hrefFor(lang, spec.secondary.path)}>{tx(spec.secondary.label, lang)} <Arrow /></a>}
        </div>
        <nav className="breadcrumb" aria-label={lang === "en" ? "Breadcrumb" : "麵包屑導覽"}>
          <a href={hrefFor(lang)}>{lang === "en" ? "Home" : "首頁"}</a><span>/</span><b>{tx(spec.eyebrow, lang)}</b>
        </nav>
      </div>
    </section>
  );
}

function PageCompass({ lang, spec }: { lang: Language; spec: RichPageSpec }) {
  const facts = [
    [lang === "en" ? "For" : "適合", tx(spec.audience, lang)],
    [lang === "en" ? "Page purpose" : "頁面目的", tx(spec.purpose, lang)],
    [lang === "en" ? "Current status" : "現時狀態", tx(spec.status, lang)],
  ];
  return <section className="rich-compass"><div className="shell rich-compass-grid">{facts.map(([label, value]) => <div key={label}><span>{label}</span><strong>{value}</strong></div>)}</div></section>;
}

function SectionItems({ lang, section }: { lang: Language; section: PageSection }) {
  const tag = section.mode === "steps" ? "ol" : "div";
  const Wrapper = tag as "ol" | "div";
  return <Wrapper className={`rich-items rich-items-${section.mode ?? "cards"}`}>
    {section.items.map((entry, index) => {
      const body = <>
        <span className="rich-item-number">{String(index + 1).padStart(2, "0")}</span>
        <h3>{tx(entry.title, lang)}</h3>
        <p>{tx(entry.copy, lang)}</p>
        {entry.path && <b>{lang === "en" ? "Continue" : "繼續"} <Arrow /></b>}
      </>;
      if (section.mode === "steps") return <li key={entry.title.en}>{body}</li>;
      return entry.path ? <a href={hrefFor(lang, entry.path)} key={entry.title.en}>{body}</a> : <article key={entry.title.en}>{body}</article>;
    })}
  </Wrapper>;
}

function ProofStory({ lang, proof }: { lang: Language; proof: RichPageSpec["proof"] }) {
  const record = proofRecords[proof];
  return <section className="rich-proof"><div className="shell rich-proof-grid">
    <figure><img src={record.image} alt={tx(record.alt, lang)} loading="lazy" decoding="async" /></figure>
    <div><p className="eyebrow light">{tx(record.label, lang)}</p><h2>{tx(record.title, lang)}</h2><p>{tx(record.copy, lang)}</p><small>{tx(record.note, lang)}</small></div>
  </div></section>;
}

function OpenParticipation({ lang, spec }: { lang: Language; spec: RichPageSpec }) {
  return <section className="section rich-open"><div className="shell">
    <div className="rich-open-panel" role="status">
      <span className="pulse-ring" aria-hidden="true" />
      <div><p className="status-label">{lang === "en" ? "Open now" : "現正開放"}</p><h2>{lang === "en" ? "No confirmed live opportunity is attached to this page." : "本頁目前未有已確認的現行機會。"}</h2><p>{lang === "en" ? "The page remains useful through its recurring pathway, verified history and clear next action. Dates, eligibility and registration appear only after approval." : "本頁仍提供恆常參與路徑、已核實歷史及清晰下一步；日期、資格及報名只會在批准後顯示。"}</p></div>
      <div><a className="button button-dark" href={hrefFor(lang, spec.primary.path)}>{tx(spec.primary.label, lang)} <Arrow /></a><a className="text-link" href={hrefFor(lang, "events?status=open")}>{lang === "en" ? "Check Open Now" : "查看現正開放"} <Arrow /></a></div>
    </div>
  </div></section>;
}

function RelatedRoutes({ lang, spec }: { lang: Language; spec: RichPageSpec }) {
  return <section className="section rich-related"><div className="shell">
    <div className="rich-section-heading"><p className="eyebrow">{lang === "en" ? "Continue through the ecosystem" : "繼續探索生態系統"}</p><h2>{lang === "en" ? "Useful routes from here." : "由這裡出發的實用途徑。"}</h2><p>{lang === "en" ? "Move between knowledge, people, activities and a practical action without reaching a dead end." : "在知識、人才、活動及實務行動之間移動，不會走進死胡同。"}</p></div>
    <div className="rich-related-grid">{spec.related.map((entry) => <a href={hrefFor(lang, entry.path)} key={entry.title.en}><span>{lang === "en" ? "Related route" : "相關路徑"}</span><h3>{tx(entry.title, lang)}</h3><p>{tx(entry.copy, lang)}</p><Arrow /></a>)}</div>
  </div></section>;
}

function RichPage({ lang, path, spec, extra }: { lang: Language; path: string; spec: RichPageSpec; extra?: ReactNode }) {
  return <>
    <RichHero lang={lang} path={path} spec={spec} />
    <PageCompass lang={lang} spec={spec} />
    {spec.sections.length > 4 && <nav className="rich-anchor-nav shell" aria-label={lang === "en" ? "On this page" : "本頁內容"}>{spec.sections.map((section) => <a href={`#${section.id}`} key={section.id}>{tx(section.eyebrow, lang)}</a>)}</nav>}
    {spec.sections.map((section, index) => <section className={`section rich-section${index % 2 ? " rich-section-tint" : ""}`} id={section.id} key={section.id}><div className="shell"><div className="rich-section-heading"><p className="eyebrow">{tx(section.eyebrow, lang)}</p><h2>{tx(section.title, lang)}</h2><p>{tx(section.copy, lang)}</p></div><SectionItems lang={lang} section={section} /></div></section>)}
    {extra}
    <OpenParticipation lang={lang} spec={spec} />
    <ProofStory lang={lang} proof={spec.proof} />
    <RelatedRoutes lang={lang} spec={spec} />
    <section className="inner-closing"><div className="shell inner-closing-grid"><div><p className="eyebrow light">{lang === "en" ? "Your next step" : "你的下一步"}</p><h2>{tx(spec.close.title, lang)}</h2><p>{tx(spec.close.copy, lang)}</p></div><div className="inner-closing-actions"><a className="button button-light" href={hrefFor(lang, spec.primary.path)}>{tx(spec.primary.label, lang)} <Arrow /></a>{spec.secondary && <a className="text-link light-link" href={hrefFor(lang, spec.secondary.path)}>{tx(spec.secondary.label, lang)} <Arrow /></a>}</div></div></section>
  </>;
}

