function EnquiryForm({ lang, config }: { lang: Language; config: (typeof enquiryConfig)[EnquiryKind] }) {
  const [sent, setSent] = useState(false);
  const [values, setValues] = useState<Record<number, string>>({});
  const [consent, setConsent] = useState(false);
  const [error, setError] = useState("");
  const isOptional = (field: LocalText) => field.en.toLowerCase().includes("optional");
  const isMultiline = (field: LocalText) => /(problem|process|outcome|constraints|reason|context|how can|commercial or sponsorship interest)/i.test(field.en);
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const missing = config.fields.findIndex((field, index) => !isOptional(field) && !values[index]?.trim());
    if (missing >= 0) { setError(lang === "en" ? `Complete “${config.fields[missing].en}” before preparing the summary.` : `請先填寫「${config.fields[missing].zh}」。`); return; }
    if (!consent) { setError(lang === "en" ? "Confirm the privacy acknowledgement before preparing the summary." : "準備摘要前，請確認私隱聲明。"); return; }
    setError(""); setSent(true);
  };
  const body = config.fields.map((field, index) => `${field.en}: ${values[index] ?? ""}`).join("\n\n");
  return <section className="section task-form-section" id="form"><div className="shell task-form-grid">
    <div><p className="eyebrow">{lang === "en" ? "Prepare securely" : "安全準備"}</p><h2>{lang === "en" ? "Review before anything leaves your device." : "任何資料離開裝置前先檢查。"}</h2><p>{lang === "en" ? "This page prepares an email; it does not submit, pay, publish or contact another member automatically. Do not include passwords, source data, identification documents or confidential commercial information." : "本頁只準備電郵，不會自動提交、付款、發布或聯絡其他會員。請勿加入密碼、原始數據、身份證明文件或機密商業資料。"}</p></div>
    {sent ? <div className="task-summary" role="status"><span>✓</span><h3>{lang === "en" ? "Your summary is ready for review." : "你的摘要已準備好供檢查。"}</h3><p>{lang === "en" ? "Open your email application, check the recipients and wording, then choose whether to send." : "開啟電郵程式，檢查收件人及字眼，再決定是否發送。"}</p><a className="button button-dark" href={`mailto:contact@hkwtia.org?subject=${encodeURIComponent(config.subject)}&body=${encodeURIComponent(body)}`}>{lang === "en" ? "Open prepared email" : "開啟已準備電郵"} <Arrow /></a><button type="button" className="text-link" onClick={() => setSent(false)}>{lang === "en" ? "Edit the summary" : "修改摘要"}</button></div> : <form className="task-form" onSubmit={submit} noValidate>
      {error && <div className="form-error" role="alert"><strong>{lang === "en" ? "Check the form" : "請檢查表格"}</strong><p>{error}</p></div>}
      <div className="form-grid">{config.fields.map((field, index) => <label key={field.en}>{tx(field, lang)}{isMultiline(field) ? <textarea rows={field.en.toLowerCase().includes("problem") || field.en.toLowerCase().includes("how can") ? 5 : 3} value={values[index] ?? ""} onChange={(event) => setValues((current) => ({ ...current, [index]: event.target.value }))} aria-invalid={Boolean(error && !isOptional(field) && !values[index])} /> : <input type={field.en.toLowerCase().includes("email") ? "email" : "text"} value={values[index] ?? ""} onChange={(event) => setValues((current) => ({ ...current, [index]: event.target.value }))} aria-invalid={Boolean(error && !isOptional(field) && !values[index])} />}</label>)}</div>
      <label className="consent"><input type="checkbox" checked={consent} onChange={(event) => setConsent(event.target.checked)} aria-invalid={Boolean(error && !consent)} />{lang === "en" ? "I understand that I control the final email and should not include confidential or unnecessary personal data." : "我明白最終電郵由我控制，亦不應加入機密或不必要個人資料。"}</label>
      <button className="button button-dark" type="submit">{lang === "en" ? "Prepare summary" : "準備摘要"} <Arrow /></button>
    </form>}
  </div></section>;
}

function EnquiryPage({ lang, kind }: { lang: Language; kind: EnquiryKind }) {
  const config = enquiryConfig[kind];
  return <RichPage lang={lang} path={config.path} spec={config.spec} extra={<EnquiryForm lang={lang} config={config} />} />;
}

