function ProgrammeEditionPage({ lang, slug, edition }: { lang: Language; slug: string; edition: string }) {
  const aliases: Record<string, string> = { hkict: "hkict-startup-award", asa: "asia-smart-innovation-awards", tct: "tech-connect" };
  const canonical = aliases[slug] ?? slug;
  const record = programmeRecords[canonical];
  if (!record) return null;
  const verifiedEdition = canonical === "asia-smart-innovation-awards" && edition === "2025";
  const spec: RichPageSpec = {
    eyebrow: L("Programme edition", "計劃屆次"),
    title: L(`${record.name} · ${edition}`, `${record.name} · ${edition}`),
    copy: verifiedEdition
      ? L("A dated edition record with its published scope and present archive status attached.", "具日期的屆次紀錄，並清楚附上已發布範圍及現時存檔狀態。")
      : L("This structured edition route is reserved for an approved dated record. Its URL alone does not confirm that the edition existed, opened or produced an outcome.", "此結構化屆次路徑只供已批准日期紀錄使用；單憑網址不代表該屆次曾經存在、開放或產生成果。"),
    audience: record.audience,
    purpose: L("Separate edition-specific facts from current programme status", "把屆次專屬事實與現行計劃狀態分開"),
    status: verifiedEdition ? L("Completed 2025 edition record", "2025 年已完成屆次紀錄") : L("Supporting edition record not connected", "尚未接入屆次支持紀錄"),
    primary: { label: L("Review the programme", "查看計劃"), path: `programmes/${slug}` },
    secondary: { label: L("Ask about this edition", "查詢此屆次"), path: "contact?topic=programme-edition" },
    visual: verifiedEdition ? siteVisuals.gba : siteVisuals.community,
    proof: verifiedEdition ? "regional" : record.proof,
    sections: [
      { id: "edition-status", eyebrow: L("Edition status", "屆次狀態"), title: verifiedEdition ? L("Published history, not an open application.", "已發布歷史，並非開放申請。") : L("No edition claim without an approved source.", "未有已批准來源，不作屆次聲稱。"), copy: verifiedEdition ? record.fact : L("Dates, organisers, eligibility, funders, partners, results and resources remain blank until an approved source is connected.", "日期、主辦方、資格、資助者、夥伴、結果及資源會保持空白，直至接入已批准來源。"), items: [item("Current status", "現行狀態", "This edition page is not an active application route.", "此屆次頁面並非現行申請途徑。"), item("Edition boundary", "屆次界線", "Relationships and results belong only to the edition supported by their source.", "關係及結果只屬其來源所支持的屆次。"), item("Correction route", "更正途徑", "Share the exact edition, claim and supporting source with the programme team.", "向計劃團隊提供確切屆次、聲稱及支持來源。", "contact?topic=programme-edition")], mode: "cards" },
      { id: "required-record", eyebrow: L("Required record", "所需紀錄"), title: L("What a complete edition page must show.", "完整屆次頁必須顯示的內容。"), copy: L("A reliable record keeps participation, governance and results in one dated context.", "可靠紀錄會把參與、管治及結果保留在同一具日期脈絡。"), items: [item("Identity", "身份", "Official edition name, status and programme owner.", "官方屆次名稱、狀態及計劃負責方。"), item("Participation", "參與", "Confirmed eligibility, timeline, fees and application route.", "已確認資格、時間表、費用及申請途徑。"), item("Relationships", "關係", "Edition-specific organisers, funders and partners.", "屆次專屬主辦方、資助者及夥伴。"), item("Outcomes", "成果", "Approved winners, graduates, evidence and resources.", "已批准得獎者、畢業團隊、證據及資源。")], mode: "steps" },
    ],
    related: [item("Programme overview", "計劃總覽", "Review the programme purpose and current status.", "查看計劃目的及現況。", `programmes/${slug}`), item("All programmes", "所有計劃", "Compare open, active and historical routes.", "比較開放、進行中及歷史途徑。", "programmes"), item("Contact", "聯絡", "Ask the programme team about an authoritative edition record.", "向計劃團隊查詢權威屆次紀錄。", "contact")],
    close: { title: L("Use the edition record that matches the decision.", "使用與決定相符的屆次紀錄。"), copy: L("Do not reuse previous dates, eligibility, relationships or results as current information.", "不要把過往日期、資格、關係或結果當作現行資料。") },
  };
  return <RichPage lang={lang} path={`programmes/${slug}/${edition}`} spec={spec} />;
}

