function PortalSubPage({ lang, slug }: { lang: Language; slug: string }) {
  const portalModule = portalModules[slug] ?? portalModules.profile;
  return <><section className="portal-sub-hero"><div className="shell"><p className="eyebrow light">{lang === "en" ? "Member portal preview" : "會員平台預覽"}</p><h1>{tx(portalModule.title, lang)}</h1><p>{tx(portalModule.copy, lang)}</p><div className="portal-preview-notice" role="status">{lang === "en" ? "Preview only — no account or private member data is connected." : "只供預覽 — 未連接帳戶或私人會員資料。"}</div></div></section><section className="section portal-sub-page"><div className="shell portal-sub-layout"><aside><a href={hrefFor(lang, "portal")}>{lang === "en" ? "Dashboard" : "儀表板"}<Arrow /></a>{Object.keys(portalModules).map((key) => <a className={key === slug ? "active" : ""} href={hrefFor(lang, `portal/${key}`)} key={key}>{lang === "en" ? key.replaceAll("-", " ") : ({ profile: "個人專頁", company: "機構專頁", seats: "機構席位", directory: "會員名錄", introductions: "引薦", solution: "方案刊登", events: "活動", programmes: "計劃", councils: "委員會", gba: "大灣區", documents: "文件", billing: "帳單", preferences: "偏好" } as Record<string,string>)[key]}</a>)}</aside><div><div className="rich-section-heading"><p className="eyebrow">{lang === "en" ? "Opportunity workspace" : "機遇工作空間"}</p><h2>{tx(portalModule.title, lang)}</h2><p>{tx(portalModule.copy, lang)}</p></div><div className="portal-module-grid">{portalModule.cards.map(([title, copy]) => <article key={title.en}><span>—</span><h3>{tx(title, lang)}</h3><p>{tx(copy, lang)}</p><small>{lang === "en" ? "No account data connected" : "未連接帳戶資料"}</small></article>)}</div><div className="portal-empty"><h3>{lang === "en" ? "Sign-in actions are not available in this public preview." : "此公開預覽不提供登入操作。"}</h3><p>{lang === "en" ? "Contact the Association for an existing account, billing or access enquiry. This page does not create, change or expose any member record." : "如有現有帳戶、帳單或存取查詢，請聯絡商會。本頁不會建立、變更或公開任何會員紀錄。"}</p><a className="button button-dark" href={hrefFor(lang, "contact?topic=portal")}>{lang === "en" ? "Contact member support" : "聯絡會員支援"} <Arrow /></a></div></div></div></section></>;
}

