  return <><section className="portal-sub-hero join-success-hero"><div className="shell"><p className="eyebrow light">{lang === "en" ? "Membership activation" : "會籍啟動"}</p><h1>{lang === "en" ? "Welcome to WiseTech Hong Kong." : "歡迎加入 WiseTech Hong Kong。"}</h1><p>{lang === "en" ? "This preview shows the intended first actions after an approved membership completion. It is not a payment receipt or confirmation of membership." : "此預覽展示會籍獲批准後的擬議首要行動；它不是付款收據，也不代表會籍已確認。"}</p></div></section><section className="section"><div className="shell"><div className="rich-section-heading"><p className="eyebrow">{lang === "en" ? "Your activation checklist" : "你的啟動清單"}</p><h2>{lang === "en" ? "Begin with one useful action." : "由一個有用行動開始。"}</h2><p>{lang === "en" ? "The live portal should personalise the recommendation using approved account interests and entitlements.": "正式平台應根據已批准帳戶興趣及權益提供個人化建議。"}</p></div><div className="rich-items rich-items-cards">{actions.map((entry, index) => <a href={hrefFor(lang, entry.path)} key={entry.title.en}><span className="rich-item-number">{String(index + 1).padStart(2,"0")}</span><h3>{tx(entry.title, lang)}</h3><p>{tx(entry.copy, lang)}</p><b>{lang === "en" ? "Preview action" : "預覽操作"} <Arrow /></b></a>)}</div></div></section></>;
