export function NotFoundInnerPage({ lang, path }: { lang: Language; path: string }) {
  return <section className="not-found-rich"><div className="shell"><p className="eyebrow light">404</p><h1>{lang === "en" ? "This page has moved—or the opportunity has changed." : "此頁面已移動，或機會狀態已有改變。"}</h1><p>{lang === "en" ? `We could not find “/${path}”. Use search, check Open Now or contact the team if you followed an old WTIA link.` : `找不到「/${path}」。請使用搜尋、查看現正開放，或如你沿用舊 WTIA 連結，請聯絡團隊。`}</p><div className="inner-hero-actions"><a className="button button-light" href={hrefFor(lang, "search")}>{lang === "en" ? "Search WiseTech" : "搜尋 WiseTech"} <Arrow /></a><a className="text-link light-link" href={hrefFor(lang, "events")}>{lang === "en" ? "Open events" : "開放活動"} <Arrow /></a><a className="text-link light-link" href={hrefFor(lang, "contact")}>{lang === "en" ? "Contact" : "聯絡"} <Arrow /></a></div></div></section>;
}

export function FullInnerRoute({ lang, path }: { lang: Language; path: string[] }): ReactNode {
  const key = path.join("/");
  if (routePages[key]) return <RichPage lang={lang} path={key} spec={routePages[key]} />;
  if (trustPages[key]) return <RichPage lang={lang} path={key} spec={trustPages[key]} />;
  if (legalPages[key]) return <RichPage lang={lang} path={key} spec={legalPages[key]} />;
  if (insightCategories[key]) return <InsightCategoryPage lang={lang} path={key} />;
  if (key === "submit-challenge") return <EnquiryPage lang={lang} kind="challenge" />;
  if (key === "request-introduction") return <EnquiryPage lang={lang} kind="introduction" />;
  if (key === "host-an-activity") return <EnquiryPage lang={lang} kind="host" />;
  if (key === "contact") return <EnquiryPage lang={lang} kind="contact" />;
  if (key === "join/success") return <JoinSuccessPage lang={lang} />;
  if (path[0] === "programmes" && path.length === 2) {
    const canonical = ({ hkict: "hkict-startup-award", asa: "asia-smart-innovation-awards", tct: "tech-connect" } as Record<string, string>)[path[1]] ?? path[1];
    return programmeRecords[canonical] ? <ProgrammeRecordPage lang={lang} slug={path[1]} /> : <NotFoundInnerPage lang={lang} path={key} />;
  }
  if (path[0] === "programmes" && path.length === 3) {
    const canonical = ({ hkict: "hkict-startup-award", asa: "asia-smart-innovation-awards", tct: "tech-connect" } as Record<string, string>)[path[1]] ?? path[1];
    return programmeRecords[canonical] ? <ProgrammeEditionPage lang={lang} slug={path[1]} edition={path[2]} /> : <NotFoundInnerPage lang={lang} path={key} />;
  }
  if (path[0] === "portal" && path[1]) return path.length === 2 && portalModules[path[1]] ? <PortalSubPage lang={lang} slug={path[1]} /> : <NotFoundInnerPage lang={lang} path={key} />;
  if (key === "404") return <NotFoundInnerPage lang={lang} path={key} />;
  return null;
}
